import * as fs from "fs-extra";
import jss from "jss";
import preset from "jss-preset-default";
import postcss from "postcss";
import * as autoprefixer from "autoprefixer";
import * as cssnano from "cssnano";

import * as elements from "../src/elements";
// import { Autosave } from "../src/elements/Autosave";
import { createTheme } from "../src/theming";
import { generateStylesheet } from "../src/css-from-js";

jss.setup({
  ...preset(),
});

const BRANDS = ["airbus", "skywise"];
const MINIFY = true;

// TODO build separate stylesheet files per breakpoints ?
// see https://www.npmjs.com/package/postcss-extract-media-query

// FIXME build minified / optimized stylesheets
// see http://goalsmashers.github.io/css-minification-benchmark/

const cssnanoPlugin: any = cssnano({
  preset: [
    "default",
    {
      normalizeWhitespace: false,
      svgo: false,
    },
  ],
});

BRANDS.forEach((brand) => {
  const theme = createTheme(brand);

  const stylesheet = Object.keys(elements)
    .map((name) => generateStylesheet(name, (elements as any)[name], theme, jss))
    .join("\n\n");
  // const stylesheet = generateStylesheet("Autosave", Autosave, theme, jss) as string;

  const plugins = MINIFY ? [autoprefixer, cssnanoPlugin] : [autoprefixer];
  postcss(plugins)
    .process(stylesheet, { from: undefined })
    .then((result: any) => {
      fs.outputFile(`dist/css/${brand}/stylesheet.css`, result.css, (err: any) => {
        if (err) {
          console.error(`Couldn't write file`, err);
          throw err;
        }
        console.log(`Generated ${brand} stylesheet`);
      });
    });
});
